'use client';

import { useRef, useState, type PointerEvent } from 'react';
import './canvas-selection-marquee.css';

export interface MarqueeShape {
  id: string;
  label: string;
  x: number;
  y: number;
  w: number;
  h: number;
  kind: 'rect' | 'circle';
}

export interface CanvasSelectionMarqueeProps {
  shapes: MarqueeShape[];
  selected: string[];
  onSelect: (ids: string[]) => void;
  label: string;
  className?: string;
}

interface Box {
  x: number;
  y: number;
  w: number;
  h: number;
}

/** Normalises a drag from any corner into a box with positive size. */
export const boxFrom = (
  x0: number,
  y0: number,
  x1: number,
  y1: number
): Box => ({
  x: Math.min(x0, x1),
  y: Math.min(y0, y1),
  w: Math.abs(x1 - x0),
  h: Math.abs(y1 - y0),
});

const hits = (a: Box, b: Box) =>
  a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y;

/**
 * Drag across the canvas in any direction to draw a selection box; every
 * shape it touches is selected as you drag. A checkbox list selects the same
 * shapes by keyboard, and Clear empties the selection.
 */
export function CanvasSelectionMarquee({
  shapes,
  selected,
  onSelect,
  label,
  className = '',
}: CanvasSelectionMarqueeProps) {
  const canvas = useRef<HTMLDivElement>(null);
  const start = useRef<{ x: number; y: number } | null>(null);
  const [box, setBox] = useState<Box | null>(null);

  const local = (event: PointerEvent) => {
    const rect = canvas.current!.getBoundingClientRect();
    return {
      x: Math.max(0, Math.min(rect.width, event.clientX - rect.left)),
      y: Math.max(0, Math.min(rect.height, event.clientY - rect.top)),
    };
  };

  return (
    <div className={`mg-marquee-sel ${className}`}>
      <div
        ref={canvas}
        className='mg-marquee-sel__canvas'
        role='img'
        aria-label={`${label}. ${selected.length} of ${shapes.length} selected.`}
        onPointerDown={(event) => {
          event.currentTarget.setPointerCapture(event.pointerId);
          start.current = local(event);
          setBox({ ...start.current, w: 0, h: 0 });
          onSelect([]);
        }}
        onPointerMove={(event) => {
          if (!start.current) return;
          const p = local(event);
          const next = boxFrom(start.current.x, start.current.y, p.x, p.y);
          setBox(next);
          onSelect(shapes.filter((s) => hits(next, s)).map((s) => s.id));
        }}
        onPointerUp={() => {
          start.current = null;
          setBox(null);
        }}
        onPointerCancel={() => {
          start.current = null;
          setBox(null);
        }}
      >
        {shapes.map((s) => (
          <span
            key={s.id}
            className='mg-marquee-sel__shape'
            data-kind={s.kind}
            data-selected={selected.includes(s.id)}
            style={{ left: s.x, top: s.y, width: s.w, height: s.h }}
          />
        ))}
        {box ? (
          <span
            className='mg-marquee-sel__box'
            style={{ left: box.x, top: box.y, width: box.w, height: box.h }}
          />
        ) : null}
      </div>
      <fieldset className='mg-marquee-sel__list'>
        <legend>Shapes</legend>
        {shapes.map((s) => (
          <label key={s.id}>
            <input
              type='checkbox'
              checked={selected.includes(s.id)}
              onChange={(event) =>
                onSelect(
                  event.target.checked
                    ? [...selected, s.id]
                    : selected.filter((id) => id !== s.id)
                )
              }
            />
            {s.label}
          </label>
        ))}
        <button
          type='button'
          onClick={() => onSelect([])}
          disabled={selected.length === 0}
        >
          Clear selection
        </button>
      </fieldset>
      <p className='mg-marquee-sel__status' role='status'>
        {selected.length} of {shapes.length} selected
      </p>
    </div>
  );
}

.mg-marquee-sel {
  display: grid;
  grid-template-columns: 1fr 110px;
  gap: 10px;
  color: var(--mg-ink, #0c1738);
}

.mg-marquee-sel__canvas {
  position: relative;
  height: 180px;
  overflow: hidden;
  border: 1px solid var(--mg-line, #d6def2);
  border-radius: 12px;
  background:
    radial-gradient(#d6def2 1px, transparent 1px) 0 0 / 14px 14px,
    #fff;
  cursor: crosshair;
  touch-action: none;
  user-select: none;
  -webkit-user-select: none;
}

.mg-marquee-sel__shape {
  position: absolute;
  border: 2px solid var(--mg-ink, #0c1738);
  border-radius: 6px;
  background: #e6ecff;
  transition:
    background-color 120ms ease,
    box-shadow 120ms ease;
}

.mg-marquee-sel__shape[data-kind='circle'] {
  border-radius: 50%;
}

.mg-marquee-sel__shape[data-selected='true'] {
  background: var(--mg-accent, #164cff);
  box-shadow: 0 0 0 3px var(--mg-green, #b6ff3b);
}

.mg-marquee-sel__box {
  position: absolute;
  border: 1.5px dashed var(--mg-accent, #164cff);
  background: rgba(22, 76, 255, 0.1);
  pointer-events: none;
}

.mg-marquee-sel__list {
  display: grid;
  gap: 2px;
  align-content: start;
  margin: 0;
  padding: 0;
  border: 0;
  font-size: 13px;
}

.mg-marquee-sel__list legend {
  margin-bottom: 4px;
  padding: 0;
  font-weight: 700;
}

.mg-marquee-sel__list label {
  display: flex;
  align-items: center;
  gap: 6px;
  min-height: 30px;
  cursor: pointer;
}

.mg-marquee-sel__list button {
  min-height: 36px;
  margin-top: 6px;
  border: 1px solid var(--mg-line-strong, #b9c5e6);
  border-radius: 8px;
  background: #fff;
  color: inherit;
  font: inherit;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
}

.mg-marquee-sel__list button:disabled {
  opacity: 0.45;
  cursor: default;
}

.mg-marquee-sel__status {
  grid-column: 1 / -1;
  margin: 0;
  color: #46527a;
  font-size: 13px;
}

@media (prefers-reduced-motion: reduce) {
  .mg-marquee-sel__shape {
    transition: none;
  }
}
